@njit
def lagrange_interpolate_2D_4points_scalar(grid1:np.ndarray, grid2: np.ndarray, scalar1: np.ndarray) -> np.ndarray:
    '''
    grid1: origin uniform grid, grid2: target grid, scalar1: data value in the origin grid.

    As for grids of different sizes, you can still interpolate it by adding irrelevant elements.

    This function try to run faster at the expense of memory and store some mapping relations into numpy arrays.
    Thus it may be obscure.
    '''
    Nx, Ny = scalar1.shape
    x_read = grid1[0]
    y_read = grid1[1]
    x = grid2[0]
    y = grid2[1]

    dx = x_read[1,0] - x_read[0,0]
    dy = y_read[0,1] - y_read[0,0]

    Nx2, Ny2 = x.shape
    scalar2 = np.full(x.shape, np.nan, dtype=np.float64)

    for i in range(Nx2):
        for j in range(Ny2):
            i_ip = int((x[i,j] - x_read[0,0]) / dx + 1)
            j_ip = int((y[i,j] - y_read[0,0]) / dy + 1)

            if i_ip-2 < 0 or i_ip+1 >= Nx or j_ip-2 < 0 or j_ip+1 >= Ny:
                continue  

            x1, x2, x3, x4 = x_read[i_ip-2, j_ip], x_read[i_ip-1, j_ip], x_read[i_ip, j_ip], x_read[i_ip+1, j_ip]
            y1, y2, y3, y4 = y_read[i_ip, j_ip-2], y_read[i_ip, j_ip-1], y_read[i_ip, j_ip], y_read[i_ip, j_ip+1]

            ax1 = (x[i,j]-x2)*(x[i,j]-x3)*(x[i,j]-x4)/((x1-x2)*(x1-x3)*(x1-x4))
            ax2 = (x[i,j]-x1)*(x[i,j]-x3)*(x[i,j]-x4)/((x2-x1)*(x2-x3)*(x2-x4))
            ax3 = (x[i,j]-x1)*(x[i,j]-x2)*(x[i,j]-x4)/((x3-x1)*(x3-x2)*(x3-x4))
            ax4 = (x[i,j]-x1)*(x[i,j]-x2)*(x[i,j]-x3)/((x4-x1)*(x4-x2)*(x4-x3))

            by1 = (y[i,j]-y2)*(y[i,j]-y3)*(y[i,j]-y4)/((y1-y2)*(y1-y3)*(y1-y4))
            by2 = (y[i,j]-y1)*(y[i,j]-y3)*(y[i,j]-y4)/((y2-y1)*(y2-y3)*(y2-y4))
            by3 = (y[i,j]-y1)*(y[i,j]-y2)*(y[i,j]-y4)/((y3-y1)*(y3-y2)*(y3-y4))
            by4 = (y[i,j]-y1)*(y[i,j]-y2)*(y[i,j]-y3)/((y4-y1)*(y4-y2)*(y4-y3))

            scalar2[i,j] = (
                by1*(ax1*scalar1[i_ip-2,j_ip-2] + ax2*scalar1[i_ip-1,j_ip-2] +
                     ax3*scalar1[i_ip  ,j_ip-2] + ax4*scalar1[i_ip+1,j_ip-2]) +
                by2*(ax1*scalar1[i_ip-2,j_ip-1] + ax2*scalar1[i_ip-1,j_ip-1] +
                     ax3*scalar1[i_ip  ,j_ip-1] + ax4*scalar1[i_ip+1,j_ip-1]) +
                by3*(ax1*scalar1[i_ip-2,j_ip  ] + ax2*scalar1[i_ip-1,j_ip  ] +
                     ax3*scalar1[i_ip  ,j_ip  ] + ax4*scalar1[i_ip+1,j_ip  ]) +
                by4*(ax1*scalar1[i_ip-2,j_ip+1] + ax2*scalar1[i_ip-1,j_ip+1] +
                     ax3*scalar1[i_ip  ,j_ip+1] + ax4*scalar1[i_ip+1,j_ip+1])
            )

    return scalar2

def scalar_field_5points_stencil(arr:np.ndarray, delta_x:float_precsion, delta_y:float_precsion) -> np.ndarray:
    '''
    Hello.

    Parameters:
    arr: A scalar field.
    delta: The step size(i.e. dx). 
    '''
    tmp_array = np.full( (2,) + arr.shape, np.nan)
    tmp_array[0][2:-2,2:-2] = (-arr[4:,2:-2]+8.0*arr[3:-1,2:-2]-8.0*arr[1:-3,2:-2]+arr[:-4,2:-2])/(12.0*delta_x)
    tmp_array[1][2:-2,2:-2] = (-arr[2:-2,4:]+8.0*arr[2:-2,3:-1]-8.0*arr[2:-2,1:-3]+arr[2:-2,:-4])/(12.0*delta_y)
    return tmp_array

def nanmean_filter1d(data, kernel_size=5, kernel=None):
    from scipy.signal import convolve
    data = np.asarray(data, dtype=float)
    if kernel is None:
        kernel = np.ones(kernel_size, dtype=float)
    data_filled = np.nan_to_num(data, nan=0.0)
    mask = ~np.isnan(data)

    summed = convolve(data_filled, kernel, mode='same', method='auto')
    counts = convolve(mask.astype(float), kernel, mode='same', method='auto')

    with np.errstate(invalid='ignore', divide='ignore'):
        result = summed / counts
    result[counts == 0] = np.nan

    return result

def nanmean_filter2d(data, kernel_size=5, kernel=None):
    if kernel is None:
        kernel = np.ones((kernel_size, kernel_size), dtype=float)

    data_filled = np.nan_to_num(data, nan=0.0)
    mask = ~np.isnan(data)

    summed = convolve2d(data_filled, kernel, mode='same', boundary='fill', fillvalue=np.nan)
    counts = convolve2d(mask.astype(float), kernel, mode='same', boundary='fill', fillvalue=np.nan)

    with np.errstate(invalid='ignore', divide='ignore'):
        result = summed / counts
    result[counts == 0] = np.nan

    return result


def shift_field(field:np.ndarray, shift_x:int, shift_y:int, boundary_value:float_precsion = np.nan) -> np.ndarray:
    '''
    Example: (in the imagined 2d grid instead of numpy array)
    0 1 2 3  shift_x =  1   nan nan nan nan  
    4 5 6 7  shift_y = -1   nan 0 1 2
    7 8 9 10 ------------>  nan 4 5 6
    '''
    shifted_field = np.full(field.shape, boundary_value,dtype=float_precsion)

    if shift_x > 0 and shift_y > 0:
        shifted_field[shift_x:,shift_y:] = field[:-shift_x,:-shift_y]
    elif shift_x < 0 and shift_y > 0:
        shift_x = -shift_x
        shifted_field[:-shift_x,shift_y:] = field[shift_x:,:-shift_y]
    elif shift_x > 0 and shift_y < 0:
        shift_y = -shift_y
        shifted_field[shift_x:,:-shift_y] = field[:-shift_x,shift_y:]
    elif shift_x < 0 and shift_y < 0:
        shift_x = -shift_x
        shift_y = -shift_y
        shifted_field[:-shift_x,:-shift_y] = field[shift_x:,shift_y:]
    elif shift_x == 0 and shift_y > 0:
        shifted_field[:,shift_y:] = field[:,:-shift_y]
    elif shift_x == 0 and shift_y < 0:
        shift_y = -shift_y
        shifted_field[:,:-shift_y] = field[:,shift_y:]
    elif shift_x > 0 and shift_y == 0:
        shifted_field[shift_x:,:] = field[:-shift_x,:]
    elif shift_x < 0 and shift_y == 0:
        shift_x = -shift_x
        shifted_field[:-shift_x,:] = field[shift_x:,:]
    else:
        shifted_field[:,:] = field[:,:]
    return shifted_field

def fit_2d_poly(X, field, order, region=(slice(None), slice(None))):
    result = np.full_like(field, np.nan)
    x_ravel = X[0][region].flatten() 
    y_ravel = X[1][region].flatten()
    X_mat = polyvander2d(x_ravel, y_ravel, [order, order])
    order1= order+1

    coeffs, *_ = lstsq(X_mat, field[region].flatten(), rcond=None)
    a_field = coeffs.reshape((order+1, order+1))
    result[region] = sum(a_field[i, j] * x_ravel**i * y_ravel**j for i in range(order1) for j in range(order1)).reshape(X[0][region].shape)
    return result
