class WriteHandler():
    def __init__(self, header:list[str]):
        self.header = header

    def loaddata(self, data:list):
        assert len(self.header) == len(data), \
            'Number of data sequences must match the length of the header list.'
        lens = [len(arr) for arr in data]
        if len(set(lens)) != 1:
            raise ValueError(f"All data sequences must have the same length.")    
        self.data = data

    def write(self,filepath:str, fmt:str = '.6e'):
        '''
            fmt: 
                .6e -> scientific notation style for Fortran
                .6f -> floating number style
        '''
        nrows = len(self.data[0])
        ncols = len(self.header)
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(",".join(self.header) + "\n")
            for i in range(nrows):
                row = [f"{self.data[j][i]:{fmt}}" for j in range(ncols)]
                f.write(",".join(row) + "\n")

